#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static uint64_t rng_state = 0x123456789abcdefULL;
static uint64_t rnd64(void) {
    uint64_t z = (rng_state += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}
static uint8_t rotl8(uint8_t v, unsigned n) { return (uint8_t)((v << n) | (v >> (8-n))); }
static uint8_t rotr8(uint8_t v, unsigned n) { return (uint8_t)((v >> n) | (v << (8-n))); }
static uint8_t gfun(uint8_t a, uint8_t b, uint8_t c) { return rotl8((uint8_t)(a+b+c), 2); }
static uint32_t F(uint32_t v) {
    uint8_t x0=v&255, x1=(v>>8)&255, x2=(v>>16)&255, x3=(v>>24)&255;
    uint8_t y2=gfun(x3^x2, x1^x0, 1);
    uint8_t y3=gfun(x3, y2, 0);
    uint8_t y1=gfun(x1^x0, y2, 0);
    uint8_t y0=gfun(x0, y1, 1);
    return (uint32_t)y0 | ((uint32_t)y1<<8) | ((uint32_t)y2<<16) | ((uint32_t)y3<<24);
}
#define MAXM 256
static uint32_t masks[MAXM];
static char labels[MAXM][80];
static int n=0;
static uint32_t bitpos(unsigned byte, int k) {
    if (k < 0 || k > 7) return 0;
    return 1u << (8*byte + k);
}
static void addmask(uint32_t m, const char *label) {
    if (!m) return;
    for (int i=0;i<n;i++) if (masks[i]==m) return;
    if (n>=MAXM) { fprintf(stderr,"too many masks\n"); exit(1); }
    masks[n]=m; snprintf(labels[n],sizeof(labels[0]),"%s",label); n++;
}
