static uint32_t bitpos(unsigned byte, int k) {
    if (k < 0 || k > 7) return 0;
    return 1u << (8*byte + k);
}
static void addmask(uint32_t m, const char *label) {
    if (!m) return;
    for (int i=0;i<n;i++) if (masks[i]==m) return;
    if (n>=MAXM) { fprintf(stderr,"too many masks\n"); exit(1); }
    masks[n]=m; snprintf(labels[n],sizeof(labels[0]),"%s",label); n++;
}
int main(void) {
    /* All single-bit masks, useful as both input and output masks. */
    for (unsigned b=0;b<32;b++) {
        char lab[80]; snprintf(lab,sizeof(lab),"bit%u",b);
        addmask(1u<<b, lab);
    }
    /* Strong byte-level linear masks for the four output bytes of F. */
    for (unsigned r=0;r<4;r++) {
