        for (int i=0;i<n;i++) {
            px[i]=(uint8_t)__builtin_parity(x & masks[i]);
            qx[i]=(uint8_t)__builtin_parity(y & masks[i]);
        }
        for (int i=0;i<n;i++) {
            uint8_t pi=px[i];
            for (int j=0;j<n;j++) cnt[i][j] += (pi==qx[j]) ? 1 : -1;
        }
