        double bij=cnt[i][j]/(2.0*N), bji=cnt[j][i]/(2.0*N);
        double score=fmin(fabs(bij),fabs(bji));
        if (score < 0.02) continue;
        if (nr < 400) {
            res[nr++]=(struct Res){score,i,j,bij,bji};
        } else {
            int worst=0; for (int t=1;t<nr;t++) if (res[t].score<res[worst].score) worst=t;
            if (score>res[worst].score) res[worst]=(struct Res){score,i,j,bij,bji};
        }
    }
    for (int a=0;a<nr;a++) for (int b=a+1;b<nr;b++)
        if (res[b].score>res[a].score) { struct Res t=res[a]; res[a]=res[b]; res[b]=t; }
    printf("N=%d\n",N);
    int lim=nr<40?nr:40;
    for (int t=0;t<lim;t++) {
        int i=res[t].i,j=res[t].j;
        printf("score=%.5f  beta(i->j)=%+.5f beta(j->i)=%+.5f\n",res[t].score,res[t].bij,res[t].bji);
        printf("  alpha/mask_i = 0x%08x  %s\n",masks[i],labels[i]);
        printf("  gamma/mask_j = 0x%08x  %s\n",masks[j],labels[j]);
    }
    return 0;
}
