#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define M32 0xFFFFFFFFu
#define MAXP 64
#define NS (1u << 20)

static uint32_t Ftbl[NS];
static uint32_t Ftbl_inv[1 << 24];
static uint8_t present[1 << 24];
static uint32_t seed_for[1 << 24];

static inline uint32_t expand(uint32_t k) {
    return (k ^ (k << 16) ^ (k * 12345u)) & M32;
}

static inline uint8_t gfun(uint8_t a, uint8_t b, uint8_t c) {
    uint8_t t = (uint8_t)(a + b + c);
    return (uint8_t)((t << 2) | (t >> 6));
}

static uint32_t F(uint32_t v) {
    uint8_t x0 = (uint8_t)v, x1 = (uint8_t)(v >> 8),
            x2 = (uint8_t)(v >> 16), x3 = (uint8_t)(v >> 24);
    uint8_t y2 = gfun(x3 ^ x2, x1 ^ x0, 1);
    uint8_t y3 = gfun(x3, y2, 0);
    uint8_t y1 = gfun(x1 ^ x0, y2, 0);
    uint8_t y0 = gfun(x0, y1, 1);
    return (uint32_t)y0 | ((uint32_t)y1 << 8) | ((uint32_t)y2 << 16) | ((uint32_t)y3 << 24);
}

static uint32_t Finv(uint32_t y) {
    uint8_t y0 = (uint8_t)y, y1 = (uint8_t)(y >> 8),
            y2 = (uint8_t)(y >> 16), y3 = (uint8_t)(y >> 24);
    uint8_t s0 = (uint8_t)((y0 >> 6) | (y0 << 2));
    uint8_t x0 = (uint8_t)(s0 - y1 - 1);
    uint8_t p  = (uint8_t)(((y1 >> 6) | (y1 << 2)) - y2);
    uint8_t x3 = (uint8_t)(((y3 >> 6) | (y3 << 2)) - y2);
    uint8_t q  = (uint8_t)(((y2 >> 6) | (y2 << 2)) - p - 1);
    uint8_t x1 = (uint8_t)(p ^ x0);
    uint8_t x2 = (uint8_t)(x3 ^ q);
    return (uint32_t)x0 | ((uint32_t)x1 << 8) | ((uint32_t)x2 << 16) | ((uint32_t)x3 << 24);
}

static inline int inv_expand(uint32_t e, uint32_t *seed) {
    uint32_t h = e >> 8;
    if (present[h]) { *seed = seed_for[h]; return 1; }
    return 0;
}

static uint64_t encrypt_words(uint32_t L, uint32_t R, const uint32_t k[4]) {
    uint32_t K[4] = {expand(k[0]), expand(k[1]), expand(k[2]), expand(k[3])};
    R ^= L;
    for (int r = 0; r < 4; r++) {
        uint32_t mixed = F(R ^ K[r]);
        uint32_t t = R;
        R = L ^ mixed;
        L = t;
    }
    L ^= R;
    return ((uint64_t)R << 32) | L;
}

int main(void) {
    FILE *fp = fopen("pairs.txt", "r");
    if (!fp) { perror("pairs.txt"); return 1; }
    uint64_t P[MAXP], C[MAXP];
    int np = 0;
    while (np < MAXP && fscanf(fp, "%llu %llu", (unsigned long long *)&P[np], (unsigned long long *)&C[np]) == 2) np++;
    fclose(fp);
    if (np < 2) { fprintf(stderr, "need known pairs\n"); return 1; }
    printf("loaded %d known pairs\n", np);

    clock_t t0 = clock();
    for (uint32_t s = 0; s < NS; s++) Ftbl[s] = F(s);
    for (uint32_t s = 0; s < NS; s++) {
        uint32_t lo = Ftbl[s] & 0xFFFFFFu;
        if (!present[lo]) { present[lo] = 1; seed_for[lo] = s; }
    }
    printf("precomputation %.3fs\n", (double)(clock() - t0) / CLOCKS_PER_SEC);

    uint32_t L0 = (uint32_t)(P[0] >> 32), R0 = (uint32_t)P[0];
    uint32_t A2 = (uint32_t)(C[0] >> 32), B2 = (uint32_t)C[0];
    uint32_t p = L0 ^ R0;
    uint32_t u2 = A2 ^ B2;
    uint32_t u3 = u2 ^ A2;
    uint32_t u4 = B2;

    FILE *out = fopen("/app/recovered_key.txt", "w");
    if (!out) { perror("recovered_key.txt"); return 1; }
    int found = 0;

    t0 = clock();
    for (uint32_t s1 = 0; s1 < NS; s1++) {
        uint32_t K1 = Ftbl[s1];
        uint32_t u1 = Finv(u2 ^ K1);
        uint32_t z1 = u1 ^ p;
        uint32_t K0 = Finv(z1) ^ p;
        uint32_t s0;
        if (expand(s0 = (uint32_t)(K0 & 0xFFFFFu)) != K0) continue;

        uint32_t z3 = u3 ^ K1;
        uint32_t z4 = Finv(z3);
        uint32_t K2 = u3 ^ Ftbl[z4 & 0xFFFFFu];
        uint32_t s2;
        if (expand(s2 = (uint32_t)(K2 & 0xFFFFFu)) != K2) continue;

        uint32_t K3 = u4 ^ z4;
        uint32_t s3;
        if (!inv_expand(K3, &s3)) continue;

        int ok = 1;
        for (int i = 1; i < np; i++) {
            uint32_t k[4] = {s0, s1, s2, s3};
            if (encrypt_words((uint32_t)(P[i] >> 32), (uint32_t)P[i], k) != C[i]) { ok = 0; break; }
        }
        if (!ok) continue;

        printf("candidate: %05x %05x %05x %05x\n", s0, s1, s2, s3);
        printf("expanded: %08x %08x %08x %08x\n", expand(s0), expand(s1), expand(s2), expand(s3));
        fprintf(out, "%05x %05x %05x %05x\n", s0, s1, s2, s3);
        found++;
    }
    fclose(out);
    printf("search %.3fs; candidates %d\n", (double)(clock() - t0) / CLOCKS_PER_SEC, found);
    return found ? 0 : 2;
}
