static uint8_t rotr8(uint8_t v, unsigned n) { return (uint8_t)((v >> n) | (v << (8-n))); }
static uint8_t gfun(uint8_t a, uint8_t b, uint8_t c) { return rotl8((uint8_t)(a+b+c), 2); }
static uint32_t F(uint32_t v) {
    uint8_t x0=v&255, x1=(v>>8)&255, x2=(v>>16)&255, x3=(v>>24)&255;
    uint8_t y2=gfun(x3^x2, x1^x0, 1);
    uint8_t y3=gfun(x3, y2, 0);
    uint8_t y1=gfun(x1^x0, y2, 0);
    uint8_t y0=gfun(x0, y1, 1);
    return (uint32_t)y0 | ((uint32_t)y1<<8) | ((uint32_t)y2<<16) | ((uint32_t)y3<<24);
}
#define MAXM 256
static uint32_t masks[MAXM];
static char labels[MAXM][80];
static int n=0;
static uint32_t bitpos(unsigned byte, int k) {
    if (k < 0 || k > 7) return 0;
    return 1u << (8*byte + k);
}
static void addmask(uint32_t m, const char *label) {
    if (!m) return;
    for (int i=0;i<n;i++) if (masks[i]==m) return;
    if (n>=MAXM) { fprintf(stderr,"too many masks\n"); exit(1); }
    masks[n]=m; snprintf(labels[n],sizeof(labels[0]),"%s",label); n++;
}
int main(void) {
    /* All single-bit masks, useful as both input and output masks. */
    for (unsigned b=0;b<32;b++) {
        char lab[80]; snprintf(lab,sizeof(lab),"bit%u",b);
        addmask(1u<<b, lab);
    }
    /* Strong byte-level linear masks for the four output bytes of F. */
    for (unsigned r=0;r<4;r++) {
        for (unsigned j=2;j<8;j++) {
            int k=(int)j-2;
            uint32_t u=0;
            char lab[80];
            if (r==2) {
                for (unsigned byte=0;byte<4;byte++) u |= bitpos(byte,k);
                snprintf(lab,sizeof(lab),"y2.b%u.k%d",j,k);
            } else if (r==3) {
                u |= bitpos(3,k);
                for (unsigned byte=0;byte<4;byte++) u |= bitpos(byte,k-2);
                snprintf(lab,sizeof(lab),"y3.b%u.k%d",j,k);
            } else if (r==1) {
                u |= bitpos(1,k) | bitpos(0,k);
                for (unsigned byte=0;byte<4;byte++) u |= bitpos(byte,k-2);
                snprintf(lab,sizeof(lab),"y1.b%u.k%d",j,k);
            } else {
                u |= bitpos(0,k) | bitpos(1,k-2) | bitpos(0,k-2);
                for (unsigned byte=0;byte<4;byte++) u |= bitpos(byte,k-4);
                snprintf(lab,sizeof(lab),"y0.b%u.k%d",j,k);
            }
