        int i = res[t].i, j = res[t].j;
        printf("score=%.6f  corr(A->B)=%+.6f corr(B->A)=%+.6f\n", res[t].score, res[t].cij, res[t].cji);
        printf("  A=0x%08x %s\n", masks[i], labels[i]);
        printf("  B=0x%08x %s\n", masks[j], labels[j]);
    }
    printf("Selected reciprocal checks:\n");
    uint32_t sel[][2] = {
        {0x01010101u, 0x00040000u}, {0x02020202u, 0x00080000u},
        {0x04040404u, 0x00100000u}, {0x08080808u, 0x00200000u},
        {0x10101010u, 0x00400000u}, {0x00040000u, 0x00100000u},
        {1u<<0, 1u<<2}, {1u<<8, 1u<<10}, {1u<<16, 1u<<18}, {1u<<24, 1u<<26}
    };
    for (unsigned k = 0; k < sizeof(sel)/sizeof(sel[0]); k++) {
        int i = -1, j = -1;
        for (int t = 0; t < n; t++) {
            if (masks[t] == sel[k][0]) i = t;
            if (masks[t] == sel[k][1]) j = t;
        }
        if (i >= 0 && j >= 0)
            printf("  in 0x%08x -> out 0x%08x corr=%+.6f; reverse=%+.6f\n",
                   sel[k][0], sel[k][1], (double)cnt[i][j]/N, (double)cnt[j][i]/N);
    }
    return 0;
}
